package com.hcn2048.engine

import com.hcn2048.model.GameBoard
import com.hcn2048.model.GameStatus
import com.hcn2048.model.Position
import com.hcn2048.model.Tile

/**
 * Compact, dependency-free serialization of a [GameBoard] for resume support.
 *
 * Format: `v1|size|score|moveCount|reached2048|r,c,v;r,c,v;...`
 *
 * Loaded tiles get ids starting at [FIRST_LOADED_ID] so they never collide with ids
 * generated by a fresh [GameEngine] (which start at 1 and grow with each spawn).
 */
object GameSerializer {

    private const val VERSION = "v1"
    private const val FIRST_LOADED_ID = 1_000_000L

    fun serialize(board: GameBoard): String {
        val tiles = board.tiles.joinToString(";") { tile ->
            "${tile.position.row},${tile.position.col},${tile.value}"
        }
        return listOf(
            VERSION,
            board.size,
            board.score,
            board.moveCount,
            if (board.reached2048) 1 else 0,
            tiles,
        ).joinToString("|")
    }

    /** Returns null when [value] is missing, blank or corrupt. */
    fun deserialize(value: String?): GameBoard? {
        if (value.isNullOrBlank()) return null
        val parts = value.split("|")
        if (parts.size != 6 || parts[0] != VERSION) return null
        return try {
            val size = parts[1].toInt()
            val score = parts[2].toInt()
            val moveCount = parts[3].toInt()
            val reached = parts[4] == "1"
            var nextId = FIRST_LOADED_ID
            val tiles = if (parts[5].isEmpty()) {
                emptyList()
            } else {
                parts[5].split(";").map { entry ->
                    val (row, col, tileValue) = entry.split(",")
                    Tile(
                        id = nextId++,
                        value = tileValue.toInt(),
                        position = Position(row.toInt(), col.toInt()),
                    )
                }
            }
            GameBoard(
                size = size,
                tiles = tiles,
                score = score,
                moveCount = moveCount,
                status = GameStatus.Playing,
                reached2048 = reached,
            )
        } catch (_: Exception) {
            null
        }
    }
}
